// PATCH /v1/admin/models of NEAR AI's live API (cloud-api openapi): the body is a map keyed by model name, each value an
// UpdateModelApiRequest (camelCase; prices in nano-USD per token, so USD per 1M tokens × 1000). A model name holds ONE providerConfig
// (the upsert merges into it), so a row is written only for weights NEAR does not list. A model NEAR already lists (matched by its
// modelId) and a name NEAR already uses as an alias are NEAR's naming choice: reported below, never sent.
const e = $('Provider entry').first().json;
const wall = $('Read the Taifoon catalogue').first().json.data ?? [];
const near = $("Read NEAR AI's model list").first().json.models ?? [];
const base = (s) => String(s ?? '').toLowerCase().replace(/^[^/]+\//, '').replace(/-(fp8|bf16|fp4|int4|int8|awq)$/, '').replace(/-instruct$/, '');
const perToken = (usdPerMtok) => ({ amount: Math.round(usdPerMtok * 1000), currency: 'USD' });
const usdPer1m = (c) => (c && Number.isFinite(c.amount) ? c.amount * 1e6 / 10 ** (c.scale ?? 9) : null);
const listed = new Map(near.map((m) => [base(m.modelId), m]));
const alias = new Map();
for (const m of near) for (const a of m.metadata?.aliases ?? []) alias.set(String(a).toLowerCase(), m.modelId);
const body = {}, naming_choice = [], alias_taken = [], skipped = [];
for (const m of wall) {
  const t = m.taifoon ?? {}, id = t.model_identity ?? {}, p = t.usd_per_1m ?? {};
  if (id.venue === 'near-ai' || m.owned_by === 'near-ai') { skipped.push({ model: m.id, why: 'served by NEAR AI itself' }); continue; }
  const quote = { in: Number(p.in), out: Number(p.out) };
  if (t.available === false || !Number.isFinite(quote.in) || !Number.isFinite(quote.out)) { skipped.push({ model: m.id, why: 'no live price' }); continue; }
  const weights = id.weights ?? m.id;
  const theirs = listed.get(base(weights));
  if (theirs) {
    naming_choice.push({ near_model: theirs.modelId, taifoon_model: m.id, weights, near_usd_per_1m: { in: usdPer1m(theirs.inputCostPerToken), out: usdPer1m(theirs.outputCostPerToken) }, taifoon_usd_per_1m: quote });
    continue;
  }
  if (alias.has(weights.toLowerCase())) { alias_taken.push({ name: weights, alias_of: alias.get(weights.toLowerCase()), taifoon_model: m.id, taifoon_usd_per_1m: quote }); continue; }
  body[weights] = {
    modelDisplayName: id.name ?? m.id,
    modelDescription: (id.name ?? m.id) + ' through Taifoon (' + e.base_url + '), an external OpenAI-compatible provider; not a TEE route.',
    ownedBy: e.name,
    providerType: 'external',
    providerConfig: { backend: e.backend, base_url: e.base_url, model_name: m.id },
    inputCostPerToken: perToken(quote.in),
    outputCostPerToken: perToken(quote.out),
    attestationSupported: false,
    verifiable: false,
    huggingFaceId: weights,
    ...(id.quant && id.quant !== 'unknown' ? { quantization: id.quant } : {}),
    inputModalities: ['text'],
    outputModalities: ['text'],
    isActive: true,
    isListed: true,
  };
}
return [{ json: { body, count: Object.keys(body).length, naming_choice, alias_taken, skipped } }];

const b = $('Shape the admin batch').first().json;
return [{ json: {
  models_written: Object.keys(b.body),
  first_rows: Object.entries(b.body).slice(0, 3).map(([name, m]) => ({ model: name, model_name: m.providerConfig.model_name, in_usd_per_mtok: m.inputCostPerToken.amount / 1000, out_usd_per_mtok: m.outputCostPerToken.amount / 1000 })),
  needs_near_naming_choice: b.naming_choice,
  alias_taken: b.alias_taken,
  skipped: b.skipped,
  then: ['run the PATCH on your n8n with your admin credential (read_write) and TAIFOON_API_KEY set', 'a model you already list is one providerConfig per name: switch its upstream or list ours under a new name, your choice', 'reconcile each day with workflow 22'],
  docs: 'https://www.taifoon.io/docs/provider-entry',
} }];
